-- =============================================================
-- DEV SEED — GENERATED FILE. Do not edit by hand.
--
--   Regenerate:  python3 scripts/generate-seed.py --source-dir <dir>
--
-- Derived from the client's own catalogue export (Agrob Buchtal,
-- 2025-04-14): 6,170 articles in 667 product groups, of which the
-- 500 below are seeded. Every series and product category is
-- represented so the grid, facets and variant counts look like the real
-- catalogue rather than like test data.
--
-- A product is Series + Product type + Format; its SKUs are the article
-- numbers, which vary by colour. Capped at 12 SKUs per product.
--
-- Product/series/colour names are the client's own, in German and
-- English, so their team recognises the data on sight.
-- NOT for production.
-- =============================================================
SET search_path TO catalog;

INSERT INTO locale (code, name, is_base) VALUES
  ('de-DE', 'Deutsch',      true),
  ('en-GB', 'English (UK)', false),
  ('fr-FR', 'Français',     false);

INSERT INTO brand (code, status) VALUES
  ('agrob_buchtal', 'active'),
  ('drytile',       'active');

INSERT INTO brand_tr (brand_id, locale_code, name)
SELECT b.id, l.code,
       CASE b.code WHEN 'agrob_buchtal' THEN 'Agrob Buchtal' ELSE 'DryTile' END
FROM brand b CROSS JOIN locale l WHERE l.code IN ('de-DE','en-GB');

-- Taxonomy mirrors the client's own hierarchy: product category, then series.
INSERT INTO taxonomy_node (code, node_type, parent_id, path, depth) VALUES
  ('agrob', 'FAMILY', NULL, 'agrob', 0);

INSERT INTO taxonomy_node (code, node_type, parent_id, path, depth)
SELECT c.code, 'CATEGORY', r.id, ('agrob.' || c.code)::ltree, 1
FROM (VALUES
  ('decors'),
  ('floor_tiles'),
  ('mosaic'),
  ('patio_tiles'),
  ('pool'),
  ('shower_floors'),
  ('skirtings'),
  ('stair_tiles'),
  ('wall_tiles')
) AS c(code)
CROSS JOIN (SELECT id FROM taxonomy_node WHERE code = 'agrob') r;

