-- Attribute model built from the client's own tile properties: typed,
-- grouped and unit-bearing, so the Attributes tab renders real controls
-- (selects for lists, numerics with units) rather than free text.
INSERT INTO attribute_group (code, sort_order) VALUES
  ('technical', 1),
  ('appearance', 2),
  ('surface', 3),
  ('dimensions', 4),
  ('usage', 5),
  ('logistics', 6),
  ('commercial', 7),
  ('planning', 8);

