-- Products. workflow_state is spread deterministically across the four
-- states so the grid's status filter and the workflow stepper have
-- something to show; it is not part of the client's data.
CREATE TEMP TABLE seed_products (
  code text, series_code text, brand text, wf text,
  name_de text, name_en text, variants int, design_de text
);

