INSERT INTO product (product_code, primary_node_id, brand_id, attribute_set_id,
                     base_locale, lifecycle_state, workflow_state, owner_display_name, updated_at)
SELECT sp.code, tn.id, b.id, s.id, 'de-DE', 'ACTIVE', sp.wf,
       (ARRAY['Anna Becker','Markus Klein','Lena Vogt','Sophie Adler'])[1 + (row_number() OVER (ORDER BY sp.code) % 4)],
       now() - ((row_number() OVER (ORDER BY sp.code)) || ' hours')::interval
FROM seed_products sp
JOIN taxonomy_node tn ON tn.code = sp.series_code
JOIN brand b ON b.code = sp.brand
CROSS JOIN attribute_set s WHERE s.code = 'tile_core';

-- Names in both locales: the client team reads German, the export is English.
-- German is the base locale and carries the design copy; English has a
-- name but no description anywhere in the export. That gap is real and
-- is left in place — it is what the Localization tab exists to show.
INSERT INTO product_tr (product_id, locale_code, name, short_desc,
                        translation_status, source)
SELECT p.id, 'de-DE', sp.name_de, nullif(sp.design_de, ''), 'approved', 'human'
FROM seed_products sp JOIN product p ON p.product_code = sp.code;

INSERT INTO product_tr (product_id, locale_code, name, short_desc,
                        translation_status, source)
SELECT p.id, 'en-GB', sp.name_en, NULL,
       CASE WHEN nullif(sp.design_de, '') IS NULL THEN 'approved'
            ELSE 'pending' END,
       'human'
FROM seed_products sp JOIN product p ON p.product_code = sp.code;

