JOIN product p ON p.product_code = v.product_code
JOIN asset a ON a.storage_key = v.storage_key;

-- A web rendition per image so the gallery can request a smaller file
-- later without changing the link. Same URI for now: the client's server
-- exposes one size.
-- The ORIGINAL, labelled as what it is.
--
-- This used to claim role='web' with the original's URI and a hard-coded 'jpg'
-- format, which meant the API reported a web rendition for 1,969 images and
-- served full-size originals — a value that could not be wrong because it was
-- not really a value. This build generates no derivatives (it stores no
-- binaries), so 'original' is the only honest role, and the API now names the
-- rendition it served rather than implying one.
--
-- Format is read from the file name rather than assumed: the export contains
-- .png and .tif alongside .jpg.
INSERT INTO asset_rendition (asset_id, role, uri, width, height, format)
SELECT a.id, 'original', a.storage_key, a.width, a.height,
       lower(nullif(substring(a.file_name from '\.([A-Za-z0-9]+)$'), ''))
FROM asset a WHERE a.asset_type = 'IMAGE';

-- =============================================================
-- Supporting modules for the remaining tabs. NOT from the client
-- export — representative values, but representative of ceramic
-- tiles (ETIM EC003001, DIN EN 14411, R-ratings) rather than of
-- the fire doors the earlier demo seed used.
-- =============================================================
INSERT INTO classification_scheme (code, version, name, purpose, sort_order) VALUES
  ('ETIM',     '9.0',  'ETIM 9.0',              'Trade partner exchange (BMEcat/ETIM)', 1),
  ('DATANORM', '5.0',  'DataNorm 5.0',          'SAP / wholesaler price and article feed', 2),
  ('BMECAT',   '2005', 'BMEcat 2005',           'Catalogue interchange format', 3),
  ('UNSPSC',   '23',   'UNSPSC',                'Procurement and spend classification', 4),
  ('SALESHIER','1.0',  'Custom Sales Hierarchy','Internal sales reporting rollup', 5),
  ('IFC',      '4.3',  'IFC 4.3',               'BIM authoring — entity and predefined type', 6),
  ('OMNICLASS','2012', 'OmniClass Table 23',    'BIM product classification (North America)', 7),
  ('UNICLASS', '2015', 'Uniclass 2015',         'BIM product classification (UK)', 8);

INSERT INTO classification_class (scheme_id, code, label, path)
SELECT s.id, v.code, v.label, v.path::ltree FROM (VALUES
  ('ETIM',     'EC003001', 'Ceramic tile',            'etim.ec003001'),
  ('ETIM',     'EC003002', 'Mosaic tile',             'etim.ec003002'),
  ('ETIM',     'EC010101', 'Skirting',                'etim.ec010101'),
  ('DATANORM', '100',      'Satzart 100 / 200',       'datanorm.a100'),
  ('BMECAT',   'T-CER-01', 'Catalog group T-CER-01',  'bmecat.t_cer_01'),
  ('UNSPSC',   '30161702', 'Ceramic tiles',           'unspsc.n30161702'),
  ('SALESHIER','TILE-WALL-CER', 'Tiles > Wall > Ceramic', 'sales.tile.wall.cer'),
  ('IFC',      'IfcCovering.FLOORING', 'IfcCovering / FLOORING', 'ifc.covering.flooring'),
  ('IFC',      'IfcCovering.CLADDING', 'IfcCovering / CLADDING', 'ifc.covering.cladding'),
  ('OMNICLASS','23-15 11 17 11', 'Ceramic Tile Flooring',  'omniclass.n23_15_11_17_11'),
  ('UNICLASS', 'Pr_25_57_90_18', 'Ceramic tiles',          'uniclass.pr_25_57_90_18')
) AS v(scheme, code, label, path) JOIN classification_scheme s ON s.code = v.scheme;

-- ETIM 9.0 declares 14 features for the ceramic tile class.
INSERT INTO classification_feature (scheme_id, class_id, code, name, data_type, unit, is_required, sort_order)
SELECT s.id, c.id, v.code, v.name, v.data_type, v.unit, v.req, v.sort_order
FROM classification_scheme s
JOIN classification_class c ON c.scheme_id = s.id AND c.code = 'EC003001'
CROSS JOIN (VALUES
  ('EF000008', 'Length',                'numeric', 'mm', true,   1),
  ('EF000009', 'Width',                 'numeric', 'mm', true,   2),
  ('EF000011', 'Thickness',             'numeric', 'mm', true,   3),
  ('EF000007', 'Material',              'alpha',   NULL, true,   4),
  ('EF000234', 'Frost resistant',       'logical', NULL, true,   5),
  ('EF000099', 'Surface finish',        'alpha',   NULL, false,  6),
  ('EF000012', 'Colour',                'alpha',   NULL, false,  7),
  ('EF000045', 'Weight per m2',         'numeric', 'kg', false,  8),
  ('EF000067', 'Slip resistance class', 'alpha',   NULL, false,  9),
  ('EF000088', 'Suitable for walls',    'logical', NULL, false, 10),
  ('EF000110', 'Suitable for floors',   'logical', NULL, false, 11),
  ('EF000121', 'Glazed',                'logical', NULL, false, 12),
  ('EF000132', 'Abrasion class',        'alpha',   NULL, false, 13),
  ('EF000143', 'Water absorption',      'range',   NULL, false, 14)
) AS v(code, name, data_type, unit, req, sort_order)
WHERE s.code = 'ETIM';

INSERT INTO product_classification (product_id, scheme_id, class_id, is_primary, mapped_status)
SELECT p.id, s.id, c.id, v.is_primary, 'partial'
FROM product p
JOIN (VALUES
  ('ETIM',     'EC003001',      true),
  ('DATANORM', '100',           false),
  ('BMECAT',   'T-CER-01',      false),
  ('UNSPSC',   '30161702',      false),
  ('SALESHIER','TILE-WALL-CER', false),
  ('IFC',      'IfcCovering.CLADDING', false),
  ('OMNICLASS','23-15 11 17 11', false)
) AS v(scheme, class_code, is_primary) ON true
JOIN classification_scheme s ON s.code = v.scheme
JOIN classification_class c ON c.scheme_id = s.id AND c.code = v.class_code
WHERE p.product_code = 'AB-CRAFT-EXTENDED-COVER-PLATE-31-X-30-CM';

-- 12 of the 14 features filled, so the tab's completeness figure is
-- computed from real rows and the missing-feature path has coverage.
INSERT INTO product_classification_value (product_id, feature_id, value_text, value_number, value_bool, value_unit)
SELECT p.id, f.id, v.t, v.n, v.b, f.unit
FROM product p
JOIN classification_scheme s ON s.code = 'ETIM'
JOIN classification_feature f ON f.scheme_id = s.id
JOIN (VALUES
  ('EF000008', NULL,               310::numeric, NULL::boolean),
  ('EF000009', NULL,               300,          NULL),
  ('EF000011', NULL,               15,           NULL),
  ('EF000007', 'Stoneware',        NULL,         NULL),
  ('EF000099', 'Glazed, glossy',   NULL,         NULL),
  ('EF000012', 'Reed green',       NULL,         NULL),
  ('EF000045', NULL,               22.08,        NULL),
  ('EF000067', 'no slip resistance', NULL,       NULL),
  ('EF000088', NULL,               NULL,         true),
  ('EF000110', NULL,               NULL,         false),
  ('EF000121', NULL,               NULL,         true),
  ('EF000132', 'PEI IV',           NULL,         NULL)
) AS v(code, t, n, b) ON v.code = f.code
WHERE p.product_code = 'AB-CRAFT-EXTENDED-COVER-PLATE-31-X-30-CM';

-- Certifications. The UKCA row is dated RELATIVE to seed time so the
-- 'expiring within 12 months' banner always has exactly one case to find;
-- a fixed date would stop exercising that path as time passed.
INSERT INTO compliance_document (product_id, doc_type, reference, standard, authority, valid_from, valid_to)
SELECT p.id, v.doc_type, v.reference, v.standard, v.authority, v.valid_from::date, v.valid_to
FROM product p JOIN (VALUES
  ('CE',   'CE-AB-2025-0411', 'EN 14411',             'Notified Body 0761',  '2025-01-01', '2029-12-31'::date),
  ('TEST', 'EN-ISO-10545-2',  'EN ISO 10545-2',       'FGK Höhr-Grenzhausen','2025-01-01', '2029-12-31'::date),
  ('TEST', 'DIN-51130-2025',  'DIN 51130 (R rating)', 'TÜV Rheinland',       '2025-01-01', '2029-12-31'::date),
  ('UKCA', 'UKCA-AB-2025-77', 'UKCA',                 'BM TRADA',            '2025-01-01',
           (now() + interval '8 months')::date),
  ('DOP',  'DoP-AB-14411-01', 'CPR 305/2011 / EN 14411', 'Agrob Buchtal GmbH', '2025-01-01', NULL),
  ('EPD',  'EPD-AB-00417',    'ISO 14025 / EN 15804+A2', 'IBU',                '2025-01-01', '2029-12-31'::date)
) AS v(doc_type, reference, standard, authority, valid_from, valid_to) ON true
WHERE p.product_code = 'AB-CRAFT-EXTENDED-COVER-PLATE-31-X-30-CM';

INSERT INTO sustainability_indicator (product_id, epd_doc_id, indicator, value, unit, method, stage)
SELECT p.id, d.id, v.indicator, v.value, v.unit, 'EN 15804+A2', v.stage
FROM product p
LEFT JOIN compliance_document d ON d.product_id = p.id AND d.doc_type = 'EPD'
JOIN (VALUES ('GWP', 9.7::numeric, 'kg CO2-eq', 'A1-A3'), ('recycled_content', 18, '%', NULL))
  AS v(indicator, value, unit, stage) ON true
WHERE p.product_code = 'AB-CRAFT-EXTENDED-COVER-PLATE-31-X-30-CM';

