SELECT f.id, t.id, v.relation_type, v.priority FROM (VALUES
  ('AB-CRAFT-EXTENDED-COVER-PLATE-31-X-30-CM', 'AB-OUTLETS-COVER-GRAT-OUTLET-VALVE-OUTLET-75-MM', 'ACCESSORY', 1),
  ('AB-CRAFT-EXTENDED-COVER-PLATE-31-X-30-CM', 'AB-PROFILED-EDGING-EXTERNAL-COR-RADIUS-30-MM', 'ACCESSORY', 2),
  ('AB-CRAFT-EXTENDED-COVER-PLATE-31-X-30-CM', 'AB-SKIRTINGS-EXTERNAL-COR-RADIUS-60-MM', 'COMPATIBLE', 3),
  ('AB-CRAFT-EXTENDED-COVER-PLATE-31-X-30-CM', 'AB-POOL-EDGING-TILES-EXTERNAL-COR-SHAPED-PIECE', 'COMPATIBLE', 4),
  ('AB-CRAFT-EXTENDED-COVER-PLATE-31-X-30-CM', 'AB-POOL-EDGE-SYSTEM-F-EXTERNAL-COR-140-MM-LONG', 'CROSS_SELL', 5),
  ('AB-CRAFT-EXTENDED-COVER-PLATE-31-X-30-CM', 'AB-POOL-EDGE-SYSTEM-F-GROOVED-TILE-25-X-25-CM', 'UP_SELL', 6)
) AS v(from_code, to_code, relation_type, priority)
JOIN product f ON f.product_code = v.from_code
JOIN product t ON t.product_code = v.to_code;


-- =============================================================================
-- Workflow tasks (Sprint 27)
--
-- One OPEN approval_task per product that has not reached the terminal step,
-- placed at the step the product is already in and assigned to the product's
-- OWN owner. Nothing here is invented: the step comes from
-- product.workflow_state and the assignee from product.owner_display_name.
--
-- No history rows are seeded. A transition that never happened must not appear
-- in an approval trail, so the Workflow tab starts empty for every seeded
-- product and fills as real actions are taken. Sprint 25 is the reason that
-- rule is written down: a seeded rendition that described a file nobody had
-- produced read as evidence for six sprints.
--
-- Priority is left at the default and due_date NULL for every row, which means
-- neither varies. Nothing in the UI counts or filters on them this sprint —
-- a figure that can only ever be one value looks exactly like a correct
-- figure (R-19).
-- =============================================================================

INSERT INTO approval_task (product_id, definition_id, current_step_id, assignee_display_name)
SELECT p.id, d.id, ws.id, p.owner_display_name
FROM product p
JOIN workflow_definition d ON d.entity_type = 'PRODUCT' AND d.is_active
JOIN workflow_step ws ON ws.definition_id = d.id AND ws.code = p.workflow_state
WHERE NOT ws.is_terminal;
